{"path":"/app/solution.sh","content":"#!/usr/bin/env bash
set -euo pipefail

APP_DIR="/app"
DATA_DIR="$APP_DIR/data"
MAG_CSV="$DATA_DIR/mag.csv"
PEAKS_CSV="$DATA_DIR/peaks.csv"

mkdir -p "$DATA_DIR"

make_peaks() {
  awk -F, '
    BEGIN {
      OFS=",";
      print "frame","f1_bin","f2_bin","f3_bin";
    }
    NR == 1 {
      next;
    }
    {
      frame = $1 + 0;
      bin = $2 + 0;
      val = $3 + 0.0;

      if (!(frame in seen)) {
        seen[frame] = 1;
        order[++nframes] = frame;
        b1[frame] = b2[frame] = b3[frame] = -1;
        v1[frame] = v2[frame] = v3[frame] = -1;
      }

      if (val > v1[frame] || (val == v1[frame] && bin < b1[frame])) {
        v3[frame] = v2[frame]; b3[frame] = b2[frame];
        v2[frame] = v1[frame]; b2[frame] = b1[frame];
        v1[frame] = val;       b1[frame] = bin;
      } else if (val > v2[frame] || (val == v2[frame] && bin < b2[frame])) {
        v3[frame] = v2[frame]; b3[frame] = b2[frame];
        v2[frame] = val;       b2[frame] = bin;
      } else if (val > v3[frame] || (val == v3[frame] && bin < b3[frame])) {
        v3[frame] = val;       b3[frame] = bin;
      }
    }
    END {
      for (i = 1; i <= nframes; i++) {
        frame = order[i];
        print frame, b1[frame], b2[frame], b3[frame];
      }
    }
  ' "$MAG_CSV" > "$PEAKS_CSV"
}

if [[ "${PEAKS_ONLY:-0}" == "1" ]]; then
  make_peaks
  exit 0
fi

python3 "$APP_DIR/audioproc.py"
make_peaks
"}

